const CONFIG_PATH = path.resolve(__dirname, '../config.json');

function loadConfig() {
  const raw = fs.readFileSync(CONFIG_PATH, 'utf-8');
  return JSON.parse(raw);
}

// CommonJS exports
module.exports = { loadConfig, CONFIG_PATH };
